// Original logic from parseEuros
function parseEurosOriginal(s) {
  s = String(s).trim().replace(/^€\s*|\s*€$/g, '');
  const result = Number(Number(s.replace(/,/g, '')).toFixed(2)) * 100;
  return { value: result, isInteger: Number.isInteger(result) };
}

const testPrices = ['12.99', '10.99', '39.95'];
for (const price of testPrices) {
  const result = parseEurosOriginal(price);
  console.log(`${price} -> ${result.value} (integer: ${result.isInteger})`);
}
